import React, { useContext } from 'react';
import { Container, Row, Col, Card, Table, Badge } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { FaUserTie } from 'react-icons/fa';
import Layout from '../common/Layout';
import { AuthContext } from '../../App';

const RoleLabels = {
  STUDENT: 'Student',
  STAFF: 'Staff',
  TRANSPORT: 'Transport',
};

function Profile() {
  const { stateAuth } = useContext(AuthContext);
  const navigate = useNavigate();
  const user = stateAuth?.user || {};
  const typ = (user.typ || '').toUpperCase();
  const roleLabel = RoleLabels[typ] || typ;

  const rows = Object.entries(user).filter(
    ([k, v]) => v !== '' && v != null
  );

  return (
    <Layout>
      <Container className="py-4">
        <Card className="shadow-sm">
          <Card.Header className="bg-primary text-white d-flex justify-content-between align-items-center">
            <h5 className="mb-0">My Profile</h5>
            <Badge bg="light" text="dark">{roleLabel}</Badge>
          </Card.Header>
          <Card.Body>
            <Row>
              <Col md={4} className="text-center mb-3">
                {user.pturl ? (
                  <img
                    src={user.pturl}
                    alt="profile"
                    className="rounded-circle"
                    style={{ width: '140px', height: '140px', objectFit: 'cover' }}
                  />
                ) : (
                  <div
                    className="rounded-circle d-inline-flex align-items-center justify-content-center"
                    style={{
                      width: '140px',
                      height: '140px',
                      backgroundColor: '#eff6ff',
                      color: '#2f54eb',
                      fontSize: '3rem',
                    }}
                  >
                    {(user.stdnm || user.stfnm || user.drvnm || 'U').charAt(0)}
                  </div>
                )}
                <h6 className="mt-3">{user.stdnm || user.stfnm || user.drvnm}</h6>
                <div className="text-muted">{user.emlid}</div>
              </Col>
              <Col md={8}>
                <Table striped hover responsive size="sm">
                  <tbody>
                    {rows.map(([k, v]) => (
                      <tr key={k}>
                        <td style={{ width: '40%', fontWeight: 600 }}>{k}</td>
                        <td>{String(v)}</td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </Col>
            </Row>
          </Card.Body>
        </Card>

        {typ === 'STAFF' && (
          <section className="dash-quick-section mt-4">
            <h6 className="dash-quick-title">Apps</h6>
            <div className="dash-quick-grid">
              <button
                className="dash-quick-card"
                onClick={() => navigate('/staff-profile')}
              >
                <div
                  className="dash-quick-icon"
                  style={{ background: '#eff6ff', color: '#2f54eb' }}
                >
                  <FaUserTie size={28} />
                </div>
                <span className="dash-quick-label">Staff Profile</span>
              </button>
            </div>
          </section>
        )}
      </Container>
    </Layout>
  );
}

export default Profile;
